package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class HelpFormatter_findWrapPos_TriageGen1Test {

    @Test
    public void testFindWrapPos_NewlineBeforeWidth() {
        HelpFormatter formatter = new HelpFormatter();
        String text = "Hello\nWorld";
        int width = 5;
        int startPos = 0;
        int result = formatter.findWrapPos(text, width, startPos);
        assertEquals(5, result);
    }

    @Test
    public void testFindWrapPos_TabBeforeWidth() {
        HelpFormatter formatter = new HelpFormatter();
        String text = "Hello\tWorld";
        int width = 5;
        int startPos = 0;
        int result = formatter.findWrapPos(text, width, startPos);
        assertEquals(5, result);
    }

    @Test
    public void testFindWrapPos_NoNewlineOrTabBeforeWidth() {
        HelpFormatter formatter = new HelpFormatter();
        String text = "HelloWorld";
        int width = 5;
        int startPos = 0;
        int result = formatter.findWrapPos(text, width, startPos);
        assertEquals(-1, result);
    }

    @Test
    public void testFindWrapPos_WrapPosAtEnd() {
        HelpFormatter formatter = new HelpFormatter();
        String text = "HelloWorld";
        int width = 5;
        int startPos = 5;
        int result = formatter.findWrapPos(text, width, startPos);
        assertEquals(10, result);
    }

    @Test
    public void testFindWrapPos_NoWhitespaceBeforeWidth() {
        HelpFormatter formatter = new HelpFormatter();
        String text = "HelloWorld";
        int width = 5;
        int startPos = 0;
        int result = formatter.findWrapPos(text, width, startPos);
        assertEquals(-1, result);
    }

    @Test
    public void testFindWrapPos_LastWhitespaceBeforeWidth() {
        HelpFormatter formatter = new HelpFormatter();
        String text = "Hello World";
        int width = 5;
        int startPos = 0;
        int result = formatter.findWrapPos(text, width, startPos);
        assertEquals(7, result);
    }

    @Test
    public void testFindWrapPos_LastWhitespaceBeforeWidth_LastChar() {
        HelpFormatter formatter = new HelpFormatter();
        String text = "Hello World";
        int width = 10;
        int startPos = 5;
        int result = formatter.findWrapPos(text, width, startPos);
        assertEquals(12, result);
    }

    @Test
    public void testFindWrapPos_NoWhitespaceBeforeWidth_LastChar() {
        HelpFormatter formatter = new HelpFormatter();
        String text = "HelloWorld";
        int width = 10;
        int startPos = 5;
        int result = formatter.findWrapPos(text, width, startPos);
        assertEquals(10, result);
    }

    @Test
    public void testFindWrapPos_WrapPosAtEnd_LastChar() {
        HelpFormatter formatter = new HelpFormatter();
        String text = "HelloWorld";
        int width = 10;
        int startPos = 10;
        int result = formatter.findWrapPos(text, width, startPos);
        assertEquals(-1, result);
    }
}
